        private System.Collections.Generic.KeyValuePair<string, string> GetView0()
        {
            return new System.Collections.Generic.KeyValuePair<string, string>("CodeFirstDatabase.EmailProvider", @"
    SELECT VALUE -- Constructing EmailProvider
        [CodeFirstDatabaseSchema.EmailProvider](T1.EmailProvider_ProviderNumber, T1.EmailProvider_Domain, T1.EmailProvider_UserName, T1.EmailProvider_Password, T1.EmailProvider_Port, T1.EmailProvider_Status, T1.EmailProvider_LastTestSendDate, T1.EmailProvider_LastTestReceivedDate)
    FROM (
        SELECT 
            T.ProviderNumber AS EmailProvider_ProviderNumber, 
            T.Domain AS EmailProvider_Domain, 
            T.UserName AS EmailProvider_UserName, 
            T.Password AS EmailProvider_Password, 
            T.Port AS EmailProvider_Port, 
            T.Status AS EmailProvider_Status, 
            T.LastTestSendDate AS EmailProvider_LastTestSendDate, 
            T.LastTestReceivedDate AS EmailProvider_LastTestReceivedDate, 
            True AS _from0
        FROM CommonDataContext.EmailProviders AS T
    ) AS T1");
        }
        
